-- Runs inside the isolated fixture transaction from media_stage3_checks.sql.
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
SET LOCAL session_replication_role=replica;
INSERT INTO public.pet_profile(id,customer_id,pet_code,pet_name,breed_id)
 SELECT pet_id,customer_id,'isolated-care-media-pet','Isolated pet',gen_random_uuid() FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001';
SET LOCAL session_replication_role=origin;
UPDATE public.appointment SET appointment_status='in_progress',check_in_time=now()-interval '1 hour' WHERE id='70000000-0000-0000-0000-000000000001';
SELECT set_config('care.appt_version',(SELECT updated_at::text FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001'),true);
SELECT set_config('care.log_version',(SELECT updated_at::text FROM public.care_log WHERE id='80000000-0000-0000-0000-000000000001'),true);
SET LOCAL ROLE authenticated;
SELECT set_config('care.session',public.prepare_media_upload(gen_random_uuid(),'care_log_image',null,'70000000-0000-0000-0000-000000000001',null,100,'image/png','evidence.png')->>'session_id',true);
SELECT set_config('care.lease',public.claim_media_upload(current_setting('care.session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('care.asset',public.finish_media_upload(current_setting('care.session')::uuid,current_setting('care.lease')::uuid,'10000000-0000-0000-0000-000000000002',repeat('d',64),2,2)::text,true);
RESET ROLE;
SELECT set_config('care.details',jsonb_build_object('title','Verified evidence','staff_id','20000000-0000-0000-0000-000000000002','note','Evidence note','recorded_at',now(),'media_asset_ids',jsonb_build_array(current_setting('care.asset')))::text,true);
SET LOCAL ROLE authenticated;
SELECT public.save_admin_service_care_log('80000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('care.appt_version')::timestamptz,current_setting('care.log_version')::timestamptz,'save',current_setting('care.details')::jsonb);
RESET ROLE;
SELECT pg_temp.assert((SELECT count(*)=2 FROM public.care_log_media WHERE care_log_id='80000000-0000-0000-0000-000000000001'),'new evidence appended to existing evidence');
SELECT pg_temp.assert((SELECT legal_hold AND status='attached' FROM public.media_asset WHERE id=current_setting('care.asset')::uuid),'evidence legal hold set');
SELECT set_config('care.appt_version',(SELECT updated_at::text FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001'),true);
SELECT set_config('care.log_version',(SELECT updated_at::text FROM public.care_log WHERE id='80000000-0000-0000-0000-000000000001'),true);
SET LOCAL ROLE authenticated;
SELECT public.save_admin_service_care_log('80000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('care.appt_version')::timestamptz,current_setting('care.log_version')::timestamptz,'save',current_setting('care.details')::jsonb);
SELECT pg_temp.assert(jsonb_array_length(public.list_care_log_media('80000000-0000-0000-0000-000000000001'))=2,'staff reader and retry no duplicates');
RESET ROLE;
SELECT set_config('care.appt_version',(SELECT updated_at::text FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001'),true);
SELECT set_config('care.log_version',(SELECT updated_at::text FROM public.care_log WHERE id='80000000-0000-0000-0000-000000000001'),true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect_error($q$SELECT public.save_admin_service_care_log('80000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('care.appt_version')::timestamptz,current_setting('care.log_version')::timestamptz,'save',jsonb_set(current_setting('care.details')::jsonb||'{"note":"must roll back"}'::jsonb,'{media_asset_ids}',jsonb_build_array(current_setting('media.test_asset'))))$q$,'42501');
SELECT pg_temp.expect_error($q$SELECT public.save_admin_service_care_log('80000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('care.appt_version')::timestamptz,current_setting('care.log_version')::timestamptz,'save',jsonb_set(current_setting('care.details')::jsonb,'{media_asset_ids}','null'))$q$,'22023');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
SELECT pg_temp.assert(jsonb_array_length(public.list_care_log_media('80000000-0000-0000-0000-000000000001'))=2,'actual customer can list own evidence');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
SELECT pg_temp.expect_error($q$SELECT public.list_care_log_media('80000000-0000-0000-0000-000000000001')$q$,'42501');
RESET ROLE;
SELECT pg_temp.assert((SELECT description='Evidence note' FROM public.care_log WHERE id='80000000-0000-0000-0000-000000000001'),'invalid media rolls back text changes');
UPDATE public.appointment SET staff_id=null WHERE id='70000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.expect_error($q$SELECT public.list_care_log_media('80000000-0000-0000-0000-000000000001')$q$,'42501');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.expect_error($q$SELECT public.list_care_log_media('80000000-0000-0000-0000-000000000001')$q$,'42501');
RESET ROLE;
